  "prediction_basis_card_ids": [
    "C09", "C15", "C16", "C07", "C10", "C17", "C30",
    "C33", "C35", "C44", "C45", "C48", "C49", "C51", "C52", "C53", "C55"
  ],
  "claims": [
    {
      "claim": "Fed-state absolute F records for ziprasidone (~59–60%) and food-insensitive F records for sertindole (~74–75%) show that lipophilic, poorly soluble drugs can meet F≥20% under fed conditions.",
      "card_ids": ["C09", "C15", "C16", "C07", "C10", "C17", "C30"]
    },
    {
      "claim": "Oral exposure records for the closely related azole posaconazole show substantial systemic exposure after oral dosing, including Cmax ~605–851 ng/mL and AUC up to 8619 ng·h/mL under fed/steady-state conditions; ketoconazole also shows meaningful oral AUC, supporting absorption for the azole scaffold.",
      "card_ids": ["C33", "C34", "C35", "C37", "C38", "C39", "C44"]
    },
    {
      "claim": "L4 Caco-2 data show posaconazole is highly permeable (Papp ~3.4–4.0 ×10^-5 cm/s), supporting adequate intestinal absorption for the query's azole-like scaffold.",
      "card_ids": ["C45", "C48", "C49", "C51", "C52", "C53", "C55"]
    },
    {
      "claim": "The low solubility values in C46/C47/C54 are limitations, but they are in vitro/formulation-specific and are not affirmative evidence of F<20%; they are outweighed by high permeability and the fed-state absorption context.",
      "card_ids": ["C46", "C47", "C54"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C45", "C46", "C47", "C48", "C49", "C51", "C52", "C53", "C54", "C55"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is provided for the query molecule (an itraconazole-type azole) or a structurally identical analog.",
    "L3/L4 records are for posaconazole and ketoconazole rather than the query; transferability is inferred from shared azole/dioxolane/piperazine scaffold and is not a direct F measurement.",
    "L4 solubility assays are in vitro and formulation-specific; the fed-state formulation, dose, and food composition for the query are unspecified.",
    "L3 exposure records lack matched IV comparators, so they do not directly quantify F.",
    "Gut-wall efflux and intestinal-metabolism evidence (L5) is not yet available."
  ],
  "decision_summary": "Predicted high (F≥20%) under fed state. Fed-condition absolute-F records for ziprasidone and sertindole, substantial oral exposure for posaconazole and ketoconazole, and high Caco-2 permeability for posaconazole support adequate absorption; low solubility is a limitation but not threshold-relevant, and no affirmative low-F evidence exists."
}

